refentry.refsect1:
&reftitle.parameters;


  request


    Une instance de Yaf_Request_Abstract à répartir.

&reftitle.returnvalues;

 L'instance de Yaf_Response_Abstract en cas de succès,
 &false; en cas d'échec, ou &null; si l'application n'est pas initialisée.

  &reftitle.examples;

   Exemple avec Yaf_Dispatcher::dispatch


<?php
$app = new Yaf_Application(dirname(__FILE__) . "/conf/application.ini");
$app->bootstrap();

// Construit une requête pointant vers ProductController::detailAction et
// la répartit manuellement.
$request = new Yaf_Request_Http("/product/detail/id/42");

$response = Yaf_Dispatcher::getInstance()->dispatch($request);

if ($response instanceof Yaf_Response_Abstract) {
    $response->response();
}
?>
